CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS mart;
CREATE SCHEMA IF NOT EXISTS app;

CREATE TABLE mart.business_units(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code varchar(32) UNIQUE NOT NULL,name varchar(100) UNIQUE NOT NULL,region varchar(50),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mart.industries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code varchar(32) UNIQUE NOT NULL,major_name varchar(100) NOT NULL,name varchar(100) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(major_name,name));
CREATE TABLE mart.product_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code varchar(32) UNIQUE NOT NULL,name varchar(100) UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mart.customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(200) UNIQUE NOT NULL,customer_level varchar(30),customer_category varchar(50),province varchar(50),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mart.contracts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),contract_no varchar(64) UNIQUE NOT NULL,opportunity_no varchar(64),contract_name varchar(200) NOT NULL,signed_at date NOT NULL,seller_name varchar(200) NOT NULL,buyer_name varchar(200),final_customer_id uuid REFERENCES mart.customers,business_unit_id uuid NOT NULL REFERENCES mart.business_units,industry_id uuid REFERENCES mart.industries,product_line_id uuid NOT NULL REFERENCES mart.product_lines,product_model varchar(100),quantity integer CHECK(quantity>=0),tax_rate numeric(6,4) CHECK(tax_rate>=0),contract_amount_tax_included numeric(18,2) NOT NULL CHECK(contract_amount_tax_included>=0),contract_amount_tax_excluded numeric(18,2) NOT NULL CHECK(contract_amount_tax_excluded>=0),status varchar(30) NOT NULL CHECK(status IN('active','cancelled','completed')),is_statistical boolean NOT NULL DEFAULT true,special_program varchar(100),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mart.revenue_facts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),contract_id uuid NOT NULL REFERENCES mart.contracts,recognized_at date NOT NULL,recognized_amount numeric(18,2) NOT NULL CHECK(recognized_amount>=0),source_type varchar(30) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mart.payment_facts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),contract_id uuid NOT NULL REFERENCES mart.contracts,paid_at date NOT NULL,payment_amount numeric(18,2) NOT NULL CHECK(payment_amount>=0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mart.sales_targets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_unit_id uuid NOT NULL REFERENCES mart.business_units,year smallint NOT NULL CHECK(year BETWEEN 2000 AND 2100),commercial_target_amount numeric(18,2) NOT NULL CHECK(commercial_target_amount>=0),solution_target_amount numeric(18,2) NOT NULL CHECK(solution_target_amount>=0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(business_unit_id,year));
CREATE TABLE mart.project_pipeline(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),contract_id uuid REFERENCES mart.contracts,opportunity_no varchar(64) UNIQUE NOT NULL,project_name varchar(200) NOT NULL,business_unit_id uuid NOT NULL REFERENCES mart.business_units,industry_id uuid REFERENCES mart.industries,product_line_id uuid REFERENCES mart.product_lines,stage varchar(30) NOT NULL,competition_risk varchar(10),signing_risk varchar(10),delivery_risk varchar(10),overall_risk varchar(10),expected_landing_date date,amount_tax_excluded numeric(18,2) CHECK(amount_tax_excluded>=0),production_scheduled boolean NOT NULL DEFAULT false,progress_note text,created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE app.qa_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id varchar(64) NOT NULL DEFAULT 'demo-user',title varchar(60) NOT NULL DEFAULT '新对话',pinned boolean NOT NULL DEFAULT false,parent_session_id uuid REFERENCES app.qa_sessions,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE app.qa_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES app.qa_sessions,role varchar(20) NOT NULL CHECK(role IN('user','assistant','system_event')),content text NOT NULL,source_message_id uuid REFERENCES app.qa_messages,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.model_configs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(50) UNIQUE NOT NULL,provider varchar(50) NOT NULL,base_url text NOT NULL,model_name varchar(100) NOT NULL,encrypted_api_key text,active boolean NOT NULL DEFAULT false,timeout_seconds integer NOT NULL DEFAULT 60 CHECK(timeout_seconds BETWEEN 1 AND 120),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE app.model_configs ADD COLUMN protocol varchar(30) NOT NULL DEFAULT 'chat_completions' CHECK(protocol IN ('responses','chat_completions'));
CREATE UNIQUE INDEX model_one_active ON app.model_configs(active) WHERE active;
CREATE TABLE app.qa_executions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_message_id uuid NOT NULL REFERENCES app.qa_messages,model_config_id uuid REFERENCES app.model_configs,status varchar(20) NOT NULL,sql_text text,row_count integer,duration_ms integer,error_code varchar(80),regenerated_from_execution_id uuid REFERENCES app.qa_executions,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
ALTER TABLE app.qa_executions ADD COLUMN model_call_audit jsonb NOT NULL DEFAULT '[]';
ALTER TABLE app.qa_executions ADD COLUMN context_message_ids jsonb NOT NULL DEFAULT '[]';
ALTER TABLE app.qa_messages ADD COLUMN execution_id uuid REFERENCES app.qa_executions(id) ON DELETE SET NULL;
CREATE INDEX qa_messages_execution_id_idx ON app.qa_messages(execution_id);
CREATE TABLE app.qa_execution_steps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),execution_id uuid NOT NULL REFERENCES app.qa_executions,step_type varchar(40) NOT NULL,status varchar(20) NOT NULL,summary text,started_at timestamptz,completed_at timestamptz);
CREATE TABLE app.qa_answer_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),assistant_message_id uuid NOT NULL REFERENCES app.qa_messages,execution_id uuid NOT NULL REFERENCES app.qa_executions,version_no integer NOT NULL,is_current boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(assistant_message_id,version_no));
CREATE TABLE app.qa_feedback(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),assistant_message_id uuid NOT NULL REFERENCES app.qa_messages,execution_id uuid NOT NULL REFERENCES app.qa_executions,reason varchar(30) NOT NULL,description varchar(500),status varchar(20) NOT NULL DEFAULT 'pending',resolution_note varchar(2000),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.favorite_questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id varchar(64) NOT NULL DEFAULT 'demo-user',normalized_question varchar(2000) NOT NULL,display_question varchar(2000) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,normalized_question));
CREATE TABLE app.data_sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(100) UNIQUE NOT NULL,description text,enabled boolean NOT NULL DEFAULT true,is_default boolean NOT NULL DEFAULT false,data_as_of date NOT NULL,allowed_objects jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.application_config(id boolean PRIMARY KEY DEFAULT true CHECK(id),greeting_enabled boolean NOT NULL DEFAULT true,greeting_text varchar(500) NOT NULL,greeting_questions jsonb NOT NULL DEFAULT '[]',followups_enabled boolean NOT NULL DEFAULT true,frequent_enabled boolean NOT NULL DEFAULT true,frequent_threshold integer NOT NULL DEFAULT 3,model_enabled boolean NOT NULL DEFAULT true,tts_enabled boolean NOT NULL DEFAULT false,stt_enabled boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());

CREATE INDEX contracts_dims_idx ON mart.contracts(business_unit_id,industry_id,product_line_id,signed_at);
CREATE INDEX revenue_date_idx ON mart.revenue_facts(recognized_at,contract_id);
CREATE INDEX payment_date_idx ON mart.payment_facts(paid_at,contract_id);
CREATE INDEX pipeline_risk_idx ON mart.project_pipeline(overall_risk,stage,business_unit_id);
CREATE INDEX session_owner_updated_idx ON app.qa_sessions(owner_id,pinned DESC,updated_at DESC) WHERE deleted_at IS NULL;
